import { Component } from '@angular/core';
import * as d3 from 'd3';

@Component({
  selector: 'app-multi-tree-list',
  templateUrl: './multi-tree-list.component.html',
  styleUrls: ['./multi-tree-list.component.css']
})
export class MultiTreeListComponent {
  // Initialize your tree data here
  public nodes = [
    {
      id: 0,
      title: 'Root',
      children: [
        {
          id: 1,
          title: 'Child 1'
        },
        {
          id: 2,
          title: 'Child 2'
        }
      ]
    }
  ];

  // Function to update the tree visualization
  private updateTree() {
    const svg = d3.select(this.rootElement);
    if (!svg.node()) return;

    svg.selectAll('*').remove();

    const node = d3.tree().size([this.width, this.height]).separation((a, b) => Math.max(0, (a.parent === b.parent ? 1 : 15) / this.nodes.length)).linkDistance(70)(nodes);

    const link = svg.append('g')
      .attr('class', 'links')
      .selectAll('.link')
      .data(node.links)
      .enter().append('path')
      .attr('class', 'link')
      .attr('d', d3.linkHorizontal()
        .x(d => d.target.x)
        .y(d => d.target.y));

    const nodeGroup = svg.append('g')
      .attr('class', 'nodes')
      .selectAll('.node')
      .data(node.descendants())
      .enter().append('g')
      .attr('class', 'node');

    nodeGroup.append('circle')
      .attr('r', 5)
      .style('fill', '#69b3a2');

    nodeGroup.append('text')
      .attr('dy', '.3em')
      .attr('dx', function(d) { return d.children || d._children ? -14 : 10; })
      .attr('text-anchor', function(d) { return d.children || d._children ? 'end' : 'start'; })
      .text(d => d.title);

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [this.width, this.height]])
      .on('zoom', () => {
        svg.attr("transform", "translate(" + d3.event.translate + ")scale(" + d3.event.scale + ")");
      });

    svg.call(zoom);
  }

  constructor(private rootElement: HTMLElement) {}
}
